    "description_en": "Marina Beach is Chennai’s iconic landmark, featuring historical statues of Tamil scholars, the Triumph of Labour statue, Mahatma Gandhi memorial, and historical lighthouse offering panoramic 360-degree views of the Bay of Bengal.",
    "description_ta": "மெரினா கடற்கரை சென்னையின் அடையாள சின்னமாகும். இங்கு திருவள்ளுவர் உள்ளிட்ட தமிழ் அறிஞர்களின் சிலைகள், உழைப்பாளர் சிலை, வரலாற்று கலங்கரை விளக்கம் மற்றும் நினைவிடங்கள் அமைந்துள்ளன.",
