    "short_desc_ta": "120 அடி உயர கம்பீரமான ராஜகோபுரம் மற்றும் புனித திருக்குளத்துடன் கூடிய 7-ஆம் நூற்றாண்டு புகழ்பெற்ற சிவன் கோவில்.",
    "description_en": "Dedicated to Lord Shiva and Goddess Karpagambal, this temple showcases exquisite Dravidian craftsmanship. Mentioned in 7th-century Tevaram hymns by the Nayanmars, it is the spiritual and cultural heart of Mylapore, famous for the annual Arupathimoovar festival.",
    "description_ta": "சிவபெருமான் மற்றும் கற்பகாம்பாள் அம்பாளுக்கு அர்ப்பணிக்கப்பட்ட இக்கோவில் மயிலாப்பூரின் ஆன்மீக பண்பாட்டு மையமாகும். தேவாரம் பாடப்பெற்ற ஸ்தலமான இங்கு பங்குனி பெருவிழா மற்றும் அறுபத்து மூவர் திருவிழா மிகச்சிறப்பாக கொண்டாடப்படுகிறது.",
