    "description_en": "Fort St. George is the historic citadel founded by the British East India Company. The Fort Museum exhibits colonial artifacts, coins, weapons, uniform relics, and original letters from Robert Clive. St. Mary’s Church inside the compound is the oldest Anglican church in India.",
    "description_ta": "1644-இல் நிறுவப்பட்ட புனித ஜார்ஜ் கோட்டை வளாகத்தில் தற்போது தமிழ்நாடு தலைமைச் செயலகம் இயங்குகிறது. இங்குள்ள அருங்காட்சியகத்தில் ஆங்கிலேயர் கால ஆவணங்கள், நாணயங்கள், உடைகள் மற்றும் பழமையான புனித மேரி தேவாலயம் அமைந்துள்ளது.",
