    "short_desc_ta": "மேற்குத் தொடர்ச்சி மலையின் இயற்கை எழில் கொஞ்சும் சூழலில் அமைந்துள்ள புகழ்பெற்ற 12-ஆம் நூற்றாண்டு முருகன் கோவில்.",
    "description_en": "Nestled amidst lush greenery of the Western Ghats at an elevation of 500 feet, Marudhamalai is regarded as the Seventh Padai Veedu of Lord Murugan. The hill is abundant in medicinal herbs (Marudham trees) and houses the sacred shrine of Pambatti Siddhar.",
    "description_ta": "மேற்கு தொடர்ச்சி மலையில் மூலிகை மரங்கள் சூழ அமைந்துள்ள மருதமலை சுப்பிரமணிய சுவாமி கோவில் முருகனின் 7-ஆம் படைவீடாக போற்றப்படுகிறது. இங்கு பாம்பாட்டி சித்தர் வாழ்ந்த குகை மற்றும் மூலிகை தீர்த்தங்கள் உள்ளன.",
