    "description_en": "Valparai is an unpolluted hill station in the Western Ghats surrounded by tea estates, rainforests, and misty peaks. Renowned for its 40 hairpin bends, scenic viewpoints (Nallamudi Poonjolai, Loam’s View Point), and wildlife sightings including the Nilgiri Tahr and Lion-tailed Macaque.",
