    "short_desc_en": "Picturesque natural cascading waterfall on the Pollachi–Valparai ghat road near Aliyar Dam.",
    "short_desc_ta": "பொள்ளாச்சி-வால்பாறை மலைப்பாதையில் ஆழியார் அணைக்கு அருகே அமைந்துள்ள புகழ்பெற்ற இயற்கை நீர்வீழ்ச்சி.",
    "description_en": "Located on the foothills of the Anaimalai Range along the Valparai Ghat road, Kavi Aruvi (popularly called Monkey Falls) is a perennial waterfall surrounded by dense rocky cliffs, managed safely under Tamil Nadu Forest Department eco-tourism.",
    "description_ta": "ஆனைமலை அடிவாரத்தில் பொள்ளாச்சி - வால்பாறை சாலையில் அமைந்துள்ள கவி அருவி குளிப்பதற்கு ஏற்ற இயற்கை நீர்வீழ்ச்சியாகும். இது தமிழ்நாடு வனத்துறையின் சூழல் சுற்றுலா திட்டத்தின் கீழ் பராமரிக்கப்படுகிறது.",
    "latitude": 10.4851,
    "longitude": 76.9691,
    "address_en": "Pollachi-Valparai Road, Aliyar, Coimbatore District - 642101",
    "address_ta": "பொள்ளாச்சி-வால்பாறை சாலை, ஆழியார், கோயம்புத்தூர் மாவட்டம் - 642101",
    "timings_en": "08:00 AM – 05:00 PM (Subject to seasonal water flow)",
