    "name_ta": "பேரூர் அருள்மிகு பட்டீஸ்வரர் சுவாமி திருக்கோவில்",
    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Over 1,500-year-old ancient Chola temple dedicated to Lord Shiva on the banks of the Noyyal River.",
    "short_desc_ta": "நொய்யல் ஆற்றங்கரையில் அமைந்துள்ள 1,500 ஆண்டுகள் பழமையான சோழர் கால வரலாற்று சிறப்புமிக்க சிவஸ்தலம்.",
    "description_en": "Perur Patteeswarar Temple, also known as Mel Chidambaram, was patronized by Karikala Chola. The architectural centerpiece is the Kanaka Sabha (Golden Hall) renowned for intricately carved stone pillars depicting the cosmic dance of Lord Nataraja.",
    "description_ta": "மேல் சிதம்பரம் என்று அழைக்கப்படும் பேரூர் பட்டீஸ்வரர் கோவில் கரிகால் சோழனால் திருப்பணி செய்யப்பட்டது. இங்குள்ள கனக சபையில் உள்ள நுணுக்கமான ஒற்றைக்கல் சிற்பத் தூண்கள் உலகப் புகழ்பெற்றவை.",
    "latitude": 10.9734,
