    "short_desc_ta": "16-ஆம் நூற்றாண்டைச் சேர்ந்த 6 அடி உயர பிரம்மாண்ட ஒற்றைக்கல் விநாயகர் சிலை வீற்றிருக்கும் புண்ணிய தலம்.",
    "description_en": "Dating back to 1500 AD, this prominent temple stands on the Coimbatore–Pollachi Highway. The massive 6-foot-tall, 3-foot-wide monolithic Ganesha deity was originally intended for the Perur temple but became enshrined here permanently.",
    "description_ta": "கோயம்புத்தூர் - பொள்ளாச்சி தேசிய நெடுஞ்சாலையில் அமைந்துள்ள ஈச்சனாரி விநாயகர் கோவில் கொங்கு மண்டலத்தின் மிக முக்கியமான வழிபாட்டுத் தலங்களில் ஒன்றாகும்.",
