    "short_desc_en": "Scenic Western Ghats waterfall surrounded by dense forests near Chadivayal, managed under eco-tourism.",
    "short_desc_ta": "சாடிவயல் அருகே மேற்கு தொடர்ச்சி மலையின் அடர்ந்த வனப்பகுதியில் அமைந்துள்ள இயற்கை எழில் கொஞ்சும் நீர்வீழ்ச்சி.",
    "description_en": "Situated around 35 km from Coimbatore, Kovai Kutralam is formed on the Siruvani hill ranges. Visitors are transported via Forest Department eco-vans from the Chadivayal checkpost to the waterfall foot.",
    "description_ta": "மேற்கு தொடர்ச்சி மலையின் இயற்கை சூழலில் அமைந்துள்ள கோவை குற்றாலம் சுற்றுலாப் பயணிகள் நீராட உகந்த அமைதியான நீர்வீழ்ச்சியாகும். சாடிவயல் சோதனைச் சாவடியிலிருந்து வனத்துறை வாகனங்கள் இயக்கப்படுகின்றன.",
    "latitude": 10.9388,
    "longitude": 76.7118,
    "address_en": "Chadivayal, Siruvani Hills, Coimbatore District - 641101",
    "address_ta": "சாடிவயல், சிறுவாணி மலை, கோயம்புத்தூர் மாவட்டம் - 641101",
    "timings_en": "10:00 AM – 03:30 PM (Closed on Mondays for forest maintenance)",
    "timings_ta": "காலை 10:00 – மதியம் 03:30 (திங்கட்கிழமைகளில் விடுமுறை)",
