    "short_desc_ta": "புனித வெள்ளியங்கிரி மலை அடிவாரத்தில் அமைந்துள்ள உலகின் மிகப்பெரிய 112 அடி உயர மார்பளவு சிலை.",
    "description_en": "Recognized by Guinness World Records as the largest bust sculpture in the world, the 112-foot Adiyogi statue celebrates the first yogi. Situated against the backdrop of the Nilgiri Biosphere Reserve and Velliangiri Hills (South Kailash).",
    "description_ta": "கின்னஸ் சாதனை புத்தகத்தில் இடம்பெற்ற 112 அடி உயர ஆதியோகி திருவுருவம் மற்றும் தென் கயிலாயம் என அழைக்கப்படும் வெள்ளியங்கிரி மலை அடிவாரத்தில் அமைந்துள்ள உலகப் புகழ்பெற்ற சுற்றுலா தலம்.",
