    "category_ta": "கோவில்",
    "short_desc_en": "Pancha Bhoota Sthalam representing the Element of Akasha (Space), world-renowned for cosmic dance of Shiva.",
    "short_desc_ta": "பஞ்ச பூத ஸ்தலங்களில் ஆகாய ஸ்தலமாக விளங்கும் ஆனந்த நடராஜரின் உலகப் புகழ்பெற்ற சிதம்பரம் திருக்கோவில்.",
    "description_en": "Dating back to the Chola period, Chidambaram Nataraja Temple is one of the holiest Shaivite shrines in the world. Spread over 51 acres with nine grand gopurams, it houses the sacred Kanaka Sabha (Golden Hall) and the mystical Chidambara Rahasya.",
    "description_ta": "சோழர் காலத்தில் பிரம்மாண்டமாக விரிவாக்கப்பட்ட சிதம்பரம் தில்லை நடராஜர் கோவில் 51 ஏக்கர் பரப்பளவில் 9 கோபுரங்கள் மற்றும் பொற்சபையுடன் அமைந்துள்ளது. இங்குள்ள சிதம்பர ரகசியம் ஆன்மீக சிறப்புடையதாகும்.",
