    "short_desc_ta": "4,400 கால்வாய்களுடன் கூடிய உலகின் இரண்டாவது மிகப்பெரிய சதுப்புநில அலையாத்திக் காடு (ராம்சார் தளம்).",
    "description_en": "Pichavaram covers 1,100 hectares of dense mangrove forests separating the Vellar and Coleroon estuaries. TTDC operates guided rowboats and motorboats gliding through narrow canopied waterways sheltering rare bird species.",
    "description_ta": "வெள்ளாறு மற்றும் கொள்ளிடம் கழிமுகங்களுக்கு இடையே 1,100 ஹெக்டேர் பரப்பளவில் அமைந்துள்ள பிச்சாவரம் அலையாத்திக் காடுகளில் படகு சவாரி மூலம் அடர்ந்த பசுமை கால்வாய்களை பார்வையிடலாம்.",
