    "short_desc_en": "Princess of Hill Stations featuring a star-shaped 60-acre lake and world-famous botanical park.",
    "short_desc_ta": "\"மலைகளின் இளவரசி\" கொடைக்கானலின் நட்சத்திர வடிவ ஏரி, படகு சவாரி மற்றும் தாவரவியல் பூங்கா.",
    "description_en": "Created in 1863 by Sir Vere Henry Levinge, the 60-acre star-shaped artificial lake is the centerpiece of Kodaikanal. Visitors enjoy pedal and row boating managed by TTDC and the Kodaikanal Boat Club, surrounded by eucalyptus and shola forests.",
    "description_ta": "1863-இல் உருவாக்கப்பட்ட 60 ஏக்கர் நட்சத்திர வடிவ கொடைக்கானல் ஏரி, படகு சவாரி, சைக்கிள் சவாரி மற்றும் அருகிலுள்ள வண்ணமயமான பிரையண்ட் பூங்காவிற்கு புகழ்பெற்றது.",
