    "short_desc_ta": "போகர் சித்தரால் நவபாஷாணத்தால் உருவாக்கப்பட்ட முருகனின் அறுபடை வீடுகளில் 3-ஆம் படைவீடு.",
    "description_en": "Perched atop Sivagiri Hill at Palani, this holy shrine attracts millions of pilgrims annually. Accessible via 693 stone steps, winch cars, and a modern ropeway car system operated by HR&CE, it is renowned for its GI-tagged Palani Panchamirtham prasadam.",
    "description_ta": "பழனி சிவகிரி மலையில் அமைந்துள்ள இத்திருத்தலம் போகர் சித்தரின் நவபாஷாண சிலையைக் கொண்டுள்ளது. புவிசார் குறியீடு (GI Tag) பெற்ற பழனி பஞ்சாமிர்தம் இங்கு சிறப்பு வாய்ந்தது.",
    "latitude": 10.4485,
