    "short_desc_en": "Oldest surviving stone structural temple in Kancheepuram, built in the late 7th century by Rajasimha Pallava.",
    "short_desc_ta": "ராஜசிம்ம பல்லவனால் 7-ஆம் நூற்றாண்டில் கட்டப்பட்ட காஞ்சிபுரத்தின் மிக பழமையான மாபெரும் கற்றளி கோவில்.",
    "description_en": "Commissioned by Narasimhavarman II (Rajasimha), Kailasanathar Temple is a masterpiece of early Dravidian stone architecture. The complex features 58 small shrines set into the compound walls containing exceptionally detailed Shaivite panel carvings.",
    "description_ta": "பல்லவ மன்னன் இரண்டாம் நரசிம்மவர்மனால் மணற்கல்லால் கட்டப்பட்ட இக்கோவில் அற்புதமான திராவிட கட்டிடக்கலையைக் கொண்டுள்ளது. 58 சிறிய சன்னதிகள் மற்றும் தனித்துவமான சிவ தாண்டவ சிற்பங்கள் இங்கு அமைந்துள்ளன.",
