    "description_en": "Covering 25 acres, this historic temple has a towering 192-foot Rajagopuram constructed by Krishnadevaraya. The sacred sthala vriksham is an ancient mango tree possessing four branches representing the four Vedas.",
    "description_ta": "25 ஏக்கர் பரப்பளவில் அமைந்துள்ள இக்கோவில் கிருஷ்ணதேவராயரால் கட்டப்பட்ட 192 அடி உயர ராஜகோபுரத்தைக் கொண்டுள்ளது. நான்கு வேதங்களைக் குறிக்கும் நான்கு சுவைகளைக் கொண்ட புனித மாமரம் இங்குள்ளது.",
