    "short_desc_ta": "இந்தியாவின் தென்முனையில் முக்கடலும் சங்கமிக்கும் இடத்தில் அமைந்துள்ள விவேகானந்தர் பாறை மற்றும் திருவள்ளுவர் சிலை.",
    "description_en": "Built on twin rocky islets 500 meters off the mainland where the Bay of Bengal, Arabian Sea, and Indian Ocean meet (Triveni Sangamam). The 133-foot stone statue of saint-poet Thiruvalluvar represents the 133 chapters of the Tirukkural. Serviced by TTDC passenger ferries.",
    "description_ta": "முக்கடல்களும் சங்கமிக்கும் முனையில் அமைந்துள்ள விவேகானந்தர் பாறை நினைவு மண்டபம் மற்றும் 133 அடி உயர பிரம்மாண்ட திருவள்ளுவர் சிலை. பூம்புகார் கப்பல் போக்குவரத்து கழகம் மூலம் படகு சேவை இயக்கப்படுகிறது.",
    "latitude": 8.078,
    "longitude": 77.555,
