    "description_en": "The heart of Madurai’s lotus-shaped city layout, Meenakshi Temple is an apex of Dravidian sculpture and architecture. The 14 gopurams reach up to 170 feet high, covered in thousands of colorful mythological stucco figures. The Hall of 1,000 Pillars houses a museum and famous musical stone pillars.",
    "description_ta": "வைகை நதிக்கரையில் அமைந்துள்ள மதுரை மீனாட்சி அம்மன் கோவில் 14 மாபெரும் கோபுரங்கள், பொற்றாமரைக்குளம் மற்றும் ஆயிரங்கால் மண்டபத்துடன் திராவிட கட்டிடக்கலையின் உலக அதிசயங்களில் ஒன்றாக திகழ்கிறது.",
