    "short_desc_ta": "1636-இல் திருமலை நாயக்கரால் கட்டப்பட்ட பிரம்மாண்ட தூண்கள் கொண்ட இந்தோ-சாரசெனிக் வரலாற்று அரண்மனை.",
    "description_en": "Built in 1636 AD with Italian architect supervision, this palace is acclaimed for its massive circular pillars measuring 82 feet in height and 19 feet in circumference, stucco dome work, and the royal courtyard (Swarga Vilasam). Hosts nightly sound & light shows.",
    "description_ta": "1636-இல் கட்டப்பட்ட இந்த அரண்மனை 82 அடி உயரமும் 19 அடி சுற்றளவும் கொண்ட பிரம்மாண்ட தூண்கள் மற்றும் சொர்க்க விலாசம் மண்டபத்தைக் கொண்டுள்ளது. தினசரி ஒலி-ஒளி காட்சி நடைபெறுகிறது.",
