    "description_en": "Velankanni Basilica, also known as the \"Lourdes of the East\", dates back to the 16th century. Elevated to a Minor Basilica by Pope John XXIII in 1962, this magnificent white Gothic basilica draws millions of pilgrims from diverse faiths every year.",
    "description_ta": "16-ஆம் நூற்றாண்டு வரலாற்றுப் பின்னணி கொண்ட வேளாங்கண்ணி அன்னை திருத்தலம் கோதிக் கட்டிடக்கலையுடன் கடலோரம் கம்பீரமாக அமைந்துள்ளது. ஆண்டுதோறும் ஆகஸ்ட்/செப்டம்பர் மாதங்களில் நடைபெறும் திருவிழா பிரசித்தி பெற்றது.",
