    "description_en": "Spanning 21 sq km of coastal dry evergreen forests, salt marshes, and tidal mudflats, Point Calimere is a world-renowned Ramsar site hosting vast congregations of migratory Greater Flamingos, spoonbills, and the endangered Blackbuck antelope.",
