    "short_desc_ta": "1687-இல் சேதுபதியால் கட்டப்பட்ட கம்பீரமான பாறைக் கோட்டை மற்றும் குடைவரைக் கோவில்கள்.",
    "description_en": "Constructed in 1687 by King Vijaya Raghunatha Sethupathi of Ramanathapuram, this semicircular fortress sits atop a monolithic boulder with concentric defensive walls, cannons, and two famous cave temples dedicated to Shiva and Vishnu.",
    "description_ta": "1687-இல் கட்டப்பட்ட திருமயம் கோட்டை ஒற்றைப் பாறையின் மீது வளைந்து செல்லும் அரண்களுடன் அமைந்துள்ளது. இங்கு சிவன் மற்றும் விஷ்ணுவுக்கான பழமையான குடைவரைக் கோவில்கள் உள்ளன.",
