    "short_desc_en": "One of the twelve sacred Jyotirlinga shrines in India, with the world’s longest pillared corridor.",
    "short_desc_ta": "12 ஜோதிர்லிங்க தலங்களில் ஒன்றான உலகின் மிக நீளமான தூண்கள் கொண்ட பிரகார திருத்தலம்.",
    "description_en": "Situated on Rameswaram island, this Char Dham pilgrimage temple has the longest temple corridor in the world, stretching over 1,220 meters with 1,212 intricately carved sandstone pillars. Pilgrims bathe in 22 sacred teerthams before worshipping Lord Ramanathaswamy.",
    "description_ta": "ராமேஸ்வரம் தீவில் அமைந்துள்ள இக்கோவில் 1,212 கலைநயமிக்க தூண்களுடன் 1,220 மீட்டர் நீளம் கொண்ட உலகின் மிக நீண்ட பிரகாரத்தைக் கொண்டுள்ளது. இங்குள்ள 22 புனித தீர்த்தங்களில் நீராடுவது சிறப்பானது.",
