    "short_desc_ta": "மக்கள் ஜனாதிபதி டாக்டர் கலாம் அவர்களின் தேசிய நினைவகம் மற்றும் வங்கக் கடல் சங்கமிக்கும் தனுஷ்கோடி.",
    "description_en": "Built by DRDO at Pei Karumbu, the memorial celebrates the life and scientific contributions of India’s 11th President Dr. A.P.J. Abdul Kalam with rare memorabilia, replicas of rockets, and paintings. Further south lies Dhanushkodi, the mystical ghost town and Rama Setu viewpoint.",
    "description_ta": "பேய்க்கரும்பில் டி.ஆர்.டி.ஓ அமைத்த டாக்டர் ஏ.பி.ஜே. அப்துல் கலாம் தேசிய நினைவகம் அவரது வாழ்க்கை வரலாற்றையும் ஏவுகணை மாதிரிகளையும் காட்சிப்படுத்துகிறது. இதன் தெற்கே அழகிய தனுஷ்கோடி கடற்கரை உள்ளது.",
