    "short_desc_ta": "1751-இல் நடைபெற்ற வரலாற்றுச் சிறப்புமிக்க ஆற்காட்டு முற்றுகையின் நினைவாக அமைந்த நுழைவாயில்.",
    "description_en": "The Delhi Gate in Arcot was part of the palatial fortress built by Chanda Sahib and later captured by Robert Clive during the 1751 Siege of Arcot. Overlooking the Palar River, it has an upper chamber where Clive held strategic war councils.",
    "description_ta": "பாலாற்றின் கரையில் அமைந்துள்ள வரலாற்றுச் சிறப்புமிக்க டெல்லி கேட் ஆற்காட்டு நவாப்கள் மற்றும் ராபர்ட் கிளைவின் ஆற்காட்டு போரோடு தொடர்புடைய பாதுகாக்கப்பட்ட நினைவுச் சின்னமாகும்.",
