    "category_ta": "மலை வாசஸ்தலம்",
    "short_desc_en": "\"Jewel of the South\" situated in the Shevaroy Hills at 1,515m, famous for coffee plantations and orange groves.",
    "short_desc_ta": "சேர்வராயன் மலைத்தொடரில் 1,515 மீ உயரத்தில் உள்ள \"ஏழைகளின் ஊட்டி\" ஏற்காடு படகு ஏரி மற்றும் அண்ணா பூங்கா.",
    "description_en": "Known as the \"Jewel of the South\", Yercaud is nestled in the Shevaroys at 1,515 meters elevation. Key attractions include the serene Yercaud Emerald Lake with TTDC boating, Lady’s Seat viewpoint, Anna Park, Pagoda Point, and Shevaroy Temple.",
    "description_ta": "சேலம் மாவட்டத்தில் அமைந்துள்ள ஏற்காடு ஏரி படகு சவாரி, லேடிஸ் சீட் காட்சி முனை, அண்ணா பூங்கா, கிளியூர் நீர்வீழ்ச்சி மற்றும் சேர்வராயன் கோவில் ஆகியவை முக்கிய ஈர்ப்புகளாகும்.",
