    "description_en": "Commissioned in 1934, Mettur Dam creates the vast Stanley Reservoir regulating irrigation across the Cauvery delta. The sprawling riverside park at the dam base features fountains, bridges, and landscaped gardens.",
    "description_ta": "1934-இல் திறக்கப்பட்ட மேட்டூர் அணை காவிரி டெல்டா பாசனத்தின் உயிர்நாடியாகும். அணையின் கீழ் அமைந்துள்ள பசுமை பூங்கா மற்றும் பவள விழா கோபுரம் பிரபல சுற்றுலா மையங்களாகும்.",
