    "description_en": "Constructed by the merchant bankers of Chettinad, this palace showcases peerless craftsmanship using imported Burmese teak pillars, Belgian crystal chandeliers, stained glass, and local Athangudi handmade tiles in an expansive multi-courtyard layout.",
    "description_ta": "கானாடுகாத்தானில் அமைந்துள்ள செட்டிநாடு அரண்மனை பரந்த முற்றங்கள், பர்மா தேக்கு மரத் தூண்கள் மற்றும் ஆத்தங்குடி கைவினைத் தரை ஓடுகளுடன் கூடிய உலகப் புகழ்பெற்ற பாரம்பரிய மையமாகும்.",
