    "category_ta": "நீர்வீழ்ச்சி",
    "short_desc_en": "\"Spa of South India\", celebrated for nine cascading waterfalls infused with Western Ghats medicinal herbs.",
    "short_desc_ta": "\"தென்னிந்தியாவின் ஸ்பா\" என்று போற்றப்படும் மேற்குத் தொடர்ச்சி மலையின் மருத்துவ குணம் கொண்ட குற்றால அருவிகள்.",
    "description_en": "Flowing from the Western Ghats Chittar River, Courtallam features nine natural waterfalls including Main Falls (Peraruvi), Five Falls (Aintharuvi), Old Courtallam, and Tiger Falls. The water is naturally infused with therapeutic forest herbs.",
    "description_ta": "மேற்கு தொடர்ச்சி மலையின் மூலிகைகளைக் கடந்து வரும் சிற்றாற்றின் பேரருவி, ஐந்தருவி, பழைய குற்றாலம் உள்ளிட்ட ஒன்பது நீர்வீழ்ச்சிகள் உடல் நலத்திற்கு உகந்த மூலிகைக் குளியலுக்கு பெயர் பெற்றவை.",
