    "description_en": "Originally built by the Thanjavur Nayaks around 1550 and later expanded by the Marathas, the palace complex houses the Saraswathi Mahal Library with over 60,000 rare palm-leaf and paper manuscripts, the Royal Museum, Bell Tower, and Arsenal Tower.",
