    "description_en": "Tiruchendur is the only one of the six sacred Padai Veedus of Lord Murugan located on the seashore. Famous for its 137-foot nine-tiered Rajagopuram, the temple stands on the spot where Lord Murugan triumphed over demon Soorapadman, celebrated annually during Soorasamharam.",
