    "short_desc_en": "Dramatic 83-meter high monolithic rock fortress dating back 3.8 billion years with 437 cut-stone steps.",
    "short_desc_ta": "3.8 பில்லியன் ஆண்டுகள் பழமையான ஒற்றைப் பாறையின் உச்சியில் 437 படிகளுடன் அமைந்த உச்சிப் பிள்ளையார் கோவில்.",
    "description_en": "Towering 83 meters over Trichy, the Rockfort rock formation is older than the Himalayas, estimated at 3.8 billion years. Accessible via 437 steps carved into the sheer rock face, the complex features 6th-century Pallava cave temples and the hilltop shrine of Ucchi Pillayar with 360-degree views of the Cauvery basin.",
    "description_ta": "இமயமலையை விடப் பழமையான 3.8 பில்லியன் ஆண்டுகள் பழமையான பாறையின் மீது 437 படிகளுடன் அமைந்துள்ள திருச்சி மலைக்கோட்டை உச்சிப் பிள்ளையார் கோவில் மற்றும் பல்லவர் குடைவரைக் கோவில்கள் வரலாற்று சிறப்புமிக்கவை.",
