    "short_desc_en": "Largest functioning temple complex in the world, spanning 156 acres with 21 grand gopurams.",
    "short_desc_ta": "156 ஏக்கர் பரப்பளவில் 21 பிரம்மாண்ட கோபுரங்கள் கொண்ட உலகின் மிகப்பெரிய செயல்படும் இந்து கோவில் வளாகம்.",
    "description_en": "Bounded by the Cauvery and Kollidam rivers, Srirangam is the premier of the 108 Divya Desams. The complex comprises 7 concentric enclosures (prakarams) and 21 gopurams, including the magnificent 236-foot Rajagopuram constructed in 1987.",
    "description_ta": "காவிரி மற்றும் கொள்ளிடம் ஆறுகளுக்கு இடையே 156 ஏக்கர் பரப்பளவில் 7 பிரகாரங்கள் மற்றும் 21 கோபுரங்களுடன் அமைந்துள்ள ஸ்ரீரங்கம் ரங்கநாதர் கோவில் யுனெஸ்கோ ஆசிய பசிபிக் விருது பெற்ற தலம்.",
