    "description_en": "Constructed by Chola King Karikalan across the Cauvery River, Kallanai is a true ancient engineering wonder. Stretching 329 meters in length, it divides the river into the Cauvery, Vennar, Kollidam, and Grand Anicut canal, irrigating millions of acres in the delta.",
    "description_ta": "காவிரி ஆற்றின் குறுக்கே 329 மீட்டர் நீளத்தில் கரிகால் சோழனால் கட்டப்பட்ட கல்லணை உலகின் மிக பழமையான நீர் பாசன அமைப்பாகும். இதன் பூங்காக்கள் மற்றும் சோழர் நினைவகம் சுற்றுலாப் பயணிகளைக் கவர்கின்றன.",
