    "short_desc_ta": "பஞ்ச தாண்டவ ஸ்தலங்களில் தாமிர சபையாக விளங்கும் இசைத் தூண்கள் கொண்ட 14 ஏக்கர் மாபெரும் கோவில்.",
    "description_en": "Spread across 14.5 acres in the center of Tirunelveli, this ancient Pandyan temple houses the famous Thamira Sabha (Copper Dance Hall of Nataraja). The Mani Mandapam features renowned cluster musical stone pillars that produce distinct melodic notes when struck.",
    "description_ta": "பாண்டிய மன்னர்களால் திருப்பணி செய்யப்பட்ட நெல்லையப்பர் கோவில் தாமிர சபை மற்றும் தட்டினால் இசை எழுப்பும் இசைத் தூண்களுக்கு புகழ்பெற்றது. தாமிரபரணி நதிக்கரையில் அமைந்துள்ள சிறப்புமிக்க தலம்.",
    "latitude": 8.7289,
    "longitude": 77.6897,
    "address_en": "South Car Street, Tirunelveli Town - 627006",
    "address_ta": "தெற்கு ரத வீதி, திருநெல்வேலி டவுன் - 627006",
    "timings_en": "05:30 AM – 12:30 PM, 04:30 PM – 09:00 PM",
