    "category": "Wildlife",
    "category_ta": "வனவிலங்கு சரணாலயம்",
    "short_desc_en": "India’s second largest brackish water lagoon, hosting up to 20,000 Greater Flamingos in winter.",
    "short_desc_ta": "இந்தியாவின் இரண்டாவது மிகப்பெரிய உவர்நீர் ஏரி மற்றும் பல்லாயிரக்கணக்கான பூநாரைகளின் புகலிடம்.",
    "description_en": "Separated from the Bay of Bengal by the barrier island of Sriharikota, Pulicat Lake covers 450 sq km. Every winter, thousands of migratory Greater Flamingos, pelicans, and herons feed in its nutrient-rich shallows.",
    "description_ta": "வங்கக் கடலோரம் 450 ச.கி.மீ பரப்பளவில் அமைந்துள்ள பழவேற்காடு ஏரி, குளிர்காலத்தில் பல்லாயிரக்கணக்கான பூநாரைகள் வந்து தங்கும் உலகப் புகழ்பெற்ற பறவைகள் சரணாலயமாகும்.",
