    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Ancient Divya Desam temple dedicated to Lord Vishnu in reclining posture, with the curative Hrit-Tapanasini tank.",
    "short_desc_ta": "108 திவ்ய தேசங்களில் ஒன்றான நோய் தீர்க்கும் ஹிருத் தாப நாசினி தீர்த்தக் குளம் கொண்ட பெருமாள் கோவில்.",
    "description_en": "One of the 108 Vaishnavite Divya Desams, this Pallava-era temple features Lord Veeraraghava reclining on Adisesha. The sacred temple tank, Hrit-Tapanasini, is venerated for possessing therapeutic medicinal properties that heal chronic diseases.",
    "description_ta": "பல்லவர் மற்றும் விஜயநகர மன்னர்களால் போற்றப்பட்ட இத்திருக்கோவிலில் ஆதிசேஷன் மீது பள்ளி கொண்ட கோலத்தில் வீரராகவ பெருமாள் அருள்பாலிக்கிறார். இங்குள்ள திருக்குளம் தீராத நோய்களைத் தீர்க்கும் சக்தி கொண்டதாக நம்பப்படுகிறது.",
