    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Pancha Bhoota Sthalam of Agni (Fire), spread across 25 acres with the 14-km sacred Arunachala Girivalam path.",
    "short_desc_ta": "பஞ்ச பூத ஸ்தலங்களில் அக்னி ஸ்தலமாக விளங்கும் 217 அடி உயர ராஜகோபுரம் கொண்ட அண்ணாமலையார் கோவில்.",
    "description_en": "Spanning 25 acres at the foot of Arunachala Hill, this legendary temple represents the element of Fire. Its Eastern Rajagopuram rises 217 feet, built by King Krishnadevaraya. The 14 km circumambulation (Girivalam) around the sacred hill draws over a million pilgrims on every Full Moon night.",
    "description_ta": "25 ஏக்கர் பரப்பளவில் அமைந்துள்ள அண்ணாமலையார் கோவில் அக்னி ஸ்தலமாகும். 217 அடி உயர ராஜகோபுரமும், பவுர்ணமி தோறும் லட்சக்கணக்கான பக்தர்கள் வலம் வரும் 14 கி.மீ கிரிவலப் பாதையும் உலகப் பிரசித்தி பெற்றவை.",
    "latitude": 12.2272,
