    "timings_en": "05:30 AM – 12:30 PM, 03:30 PM – 09:30 PM (Girivalam path open 24/7)",
    "timings_ta": "காலை 05:30 – மதியம் 12:30, மாலை 03:30 – இரவு 09:30 (கிரிவலம் 24 மணி நேரமும் செல்லலாம்)",
