    "short_desc_en": "Ancient 20-acre Shaivite temple with Asia’s largest temple chariot (Aazhi Ther) and 33-acre Kamalalayam tank.",
    "short_desc_ta": "ஆசியாவின் மிகப்பெரிய ஆழித்தேர் மற்றும் 33 ஏக்கர் பிரம்மாண்ட கமலாலயம் திருக்குளம் கொண்ட கோவில்.",
    "description_en": "Thyagaraja Temple in Tiruvarur spans over 20 acres and houses the deity of Lord Somaskanda (Thyagaraja). The 33-acre Kamalalayam sacred tank is one of the largest in India, featuring a temple in its central island. The annual Tiruvarur Chariot Festival (Aazhi Ther) is Asia’s largest moving chariot spectacle.",
    "description_ta": "20 ஏக்கர் பரப்பளவில் அமைந்துள்ள தியாகராஜர் கோவில் ஆசியாவிலேயே மிகப்பெரிய ஆழித்தேரோட்டம் மற்றும் 33 ஏக்கர் பரப்பளவிலான பிரம்மாண்ட கமலாலய திருக்குளத்திற்கு புகழ்பெற்றது.",
