    "name_ta": "வேலூர் கோட்டை & அருள்மிகு ஜலகண்டேஸ்வரர் கோவில்",
    "category": "Fort",
    "category_ta": "கோட்டை",
    "short_desc_en": "16th-century Vijayanagara granite fortress surrounded by a deep moat, venue of the 1806 Vellore Sepoy Mutiny.",
    "short_desc_ta": "16-ஆம் நூற்றாண்டு அகழியுடன் கூடிய பிரம்மாண்ட கிரானைட் கோட்டை மற்றும் 1806 சிப்பாய் புரட்சி நடைபெற்ற தளம்.",
    "description_en": "Built around 1566 by Chinna Bommi Nayak, Vellore Fort is among the finest examples of military architecture in South India, enclosed by massive granite ramparts and a deep crocodile-infested moat. Inside sits the Vijayanagara-style Jalakandeswarar Temple with intricate stone carvings, the Tipu Mahal, and the Government Museum.",
    "description_ta": "1566-இல் கட்டப்பட்ட வேலூர் கோட்டை பிரம்மாண்ட கிரானைட் சுவர்கள் மற்றும் அகழியால் சூழப்பட்டுள்ளது. உள்ளே நுணுக்கமான சிற்ப வேலைப்பாடுகள் கொண்ட ஜலகண்டேஸ்வரர் கோவில், திப்பு மஹால் மற்றும் அரசு அருங்காட்சியகம் அமைந்துள்ளன.",
