    "category": "Fort",
    "category_ta": "கோட்டை",
    "short_desc_en": "Impregnable 13th-century citadel spread over three hills (Rajagiri, Krishnagiri, Chandrayandurg), called \"Troy of the East\".",
    "short_desc_ta": "ராஜகிரி, கிருஷ்ணகிரி மலைகளில் அமைந்துள்ள யாராலும் வெல்ல முடியாத 800 ஆண்டுகள் பழமையான \"கிழக்கின் ட்ராய்\".",
    "description_en": "Dubbed the \"Troy of the East\" by Chhatrapati Shivaji, Gingee Fort spans three massive rocky hills linked by defensive walls 13 km long. Highlights include the 8-storey Kalyana Mahal, royal granary, Venkataramana Temple, and the steep citadel atop Rajagiri peak at 800 feet.",
    "description_ta": "சத்ரபதி சிவாஜியால் \"கிழக்கின் ட்ராய்\" என்று வர்ணிக்கப்பட்ட செஞ்சிக் கோட்டை 800 அடி உயர ராஜகிரி மலையில் கம்பீரமாக அமைந்துள்ளது. கல்யாண மஹால், நெற்களஞ்சியம் மற்றும் வெங்கடரமண கோவில் ஆகியவை இங்குள்ளன.",
