    "description_en": "Covering 485 sq km on the eastern slopes of the Western Ghats, this sanctuary protects the canopy-dwelling Grizzled Giant Squirrel (Ratufa macroura). Rich in biodiversity, it is also home to leopards, elephants, lion-tailed macaques, and the scenic Ayyanar Falls.",
    "description_ta": "மேற்கு தொடர்ச்சி மலையில் அமைந்துள்ள இச்சரணாலயம் அரிய வகை சாம்பல் நிற பெரிய அணில்கள், யானைகள், சிறுத்தைகள் மற்றும் அய்யனார் நீர்வீழ்ச்சிக்கு புகழ்பெற்றது.",
