    "name_en": "San Thome Basilica & National Shrine",
    "name_ta": "சாந்தோம் பசிலிக்கா பெருங்கோவில்",
    "category": "Heritage",
    "category_ta": "பாரம்பரியம்",
    "short_desc_en": "Historic 16th-century Neo-Gothic cathedral built over the tomb of St. Thomas the Apostle.",
    "short_desc_ta": "இயேசுவின் பன்னிரு சீடர்களில் ஒருவரான புனித தோமையாரின் கல்லறையின் மீது கட்டப்பட்ட பழமையான பேராலயம்.",
    "description_en": "San Thome Basilica is one of only three churches in the world built over the tomb of an apostle of Jesus Christ (the other two being in Rome and Spain). Originally built by Portuguese explorers in the 16th century and rebuilt in 1896 in striking Neo-Gothic style, it features a 155-foot spire and an adjoining museum with rare antiquities.",
    "description_ta": "இயேசுவின் அப்போஸ்தலரின் கல்லறை மீது கட்டப்பட்ட உலகின் மூன்று ஆலயங்களில் இதுவும் ஒன்றாகும். 16-ஆம் நூற்றாண்டில் போர்த்துகீசியர்களால் கட்டப்பட்டு, பின்னர் 1896-ல் பிரிட்டிஷ் நியோ-கோதிக் கட்டிடக்கலையில் 155 அடி உயர கோபுரத்துடன் கம்பீரமாக மறுவடிவமைப்பு செய்யப்பட்டது.",
