    "short_desc_ta": "இந்திய பெருநகர எல்லைக்குள் அமைந்துள்ள அரிய இயற்கை காடு மற்றும் தேசியப் பூங்கா.",
    "description_en": "Covering 2.70 sq km, Guindy National Park is an extraordinary tropical dry evergreen forest right in the heart of Chennai. It is home to blackbucks, spotted deer, jackals, pangolins, and over 150 species of birds and 60 butterfly species.",
    "description_ta": "சென்னை மாநகரின் மையப்பகுதியில் 2.70 சதுர கி.மீ பரப்பளவில் அமைந்துள்ள கிண்டி தேசியப் பூங்கா, புள்ளிமான்கள், வெளிமான்கள், குள்ளநரிகள் மற்றும் 150-க்கும் மேற்பட்ட பறவையினங்களின் இயற்கை வாழிடமாகும்.",
