    "category": "Heritage",
    "category_ta": "பாரับสนุนம்",
    "short_desc_en": "Architectural monument honoring classical Tamil poet-philosopher Thiruvalluvar with a 39-meter stone chariot.",
    "short_desc_ta": "அய்யன் திருவள்ளுவரின் நினைவாக 39 மீட்டர் உயர கல் தேர் வடிவில் எழுப்பப்பட்ட பிரம்மாண்ட நினைவு மண்டபம்.",
    "description_en": "Constructed in 1976, Valluvar Kottam is shaped like the historic temple chariot of Thiruvarur and houses a life-size statue of Thiruvalluvar. All 1,330 couplets of the revered Thirukkural are inscribed in bas-relief across the auditorium corridors.",
    "description_ta": "1976-ல் திருவாரூர் தேரின் மாதிரி அமைப்பில் 39 மீட்டர் உயரத்தில் கட்டப்பட்ட வள்ளுவர் கோட்ட வளாகத்தில், திருக்குறளின் அனைத்து 1330 குறட்பாக்களும் கருங்கல்லில் பொறிக்கப்பட்டுள்ளன.",
