    "name_ta": "திருவக்கழுக்குன்றம் வேதகிரீஸ்வரர் திருக்கோவில் (கழுகு கோவில்)",
    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Ancient hill temple dedicated to Lord Shiva, famed historically for two sacred eagles visiting daily.",
    "short_desc_ta": "இரண்டு புனித கழுகுகள் தினமும் உச்சி வேளையில் வந்து உணவு உண்ணும் வரலாற்று சிறப்புமிக்க மலைக் கோவில்.",
    "description_en": "Standing atop a 500-foot hill with 565 stone steps, the temple dates back over 1,400 years to the Pallava era. It is celebrated as one of the 275 Paadal Petra Sthalams and features an underground hill cave mandapam with ASI-protected rock inscriptions.",
    "description_ta": "565 படிகள் கொண்ட 500 அடி உயர மலை மீது அமைந்துள்ள வேதகிரீஸ்வரர் கோவில் 1400 ஆண்டுகள் பழமையான பல்லவர் கால வரலாற்றுப் பொக்கிஷமாகும்.",
