    "id": "mdu-gandhi-memorial-museum",
    "district_id": "madurai",
    "district_name_en": "Madurai",
    "district_name_ta": "மதுரை",
    "name_en": "Gandhi Memorial Museum & Tamukkam Palace",
    "name_ta": "காந்தி நினைவு அருங்காட்சியகம் மற்றும் தமுக்கம் அரண்மனை",
    "category": "Museum",
    "category_ta": "அருங்காட்சியகம்",
    "short_desc_en": "One of five Gandhi National Memorial Museums, housed in the 17th-century Nayak palace of Rani Mangammal.",
    "short_desc_ta": "17-ஆம் நூற்றாண்டு ராணி மங்கம்மாள் கோடைக்கால அரண்மனையில் அமைந்துள்ள தேசிய காந்தி நினைவு அருங்காட்சியகம்.",
    "description_en": "Inaugurated in 1959, this historical museum preserves the blood-stained garment worn by Mahatma Gandhi when he was assassinated in 1948, along with original letters and freedom movement exhibits. It was in Madurai in 1921 that Gandhi adopted the loincloth as his permanent attire.",
    "description_ta": "1959-ல் தொடங்கப்பட்ட இந்த அருங்காட்சியகத்தில், 1948-ல் காந்தியடிகள் சுடப்பட்டபோது அணிந்திருந்த இரத்தக்கறை படிந்த ஆடை, கடிதங்கள் மற்றும் விடுதலைப் போராட்ட ஆவணங்கள் பாதுகாக்கப்படுகின்றன.",
    "latitude": 9.9328,
    "longitude": 78.1408,
    "address_en": "Tamukkam, Gandhi Nagar, Madurai - 625020",
    "address_ta": "தமுக்கம், காந்தி நகர், மதுரை - 625020",
    "timings_en": "10:00 AM – 01:00 PM, 02:00 PM – 05:45 PM (Closed on Fridays)",
    "timings_ta": "காலை 10:00 – மதியம் 01:00, மதியம் 02:00 – மாலை 05:45 (வெள்ளி விடுமுறை)",
    "best_time_to_visit_en": "Throughout the year",
    "best_time_to_visit_ta": "ஆண்டு முழுவதும்",
    "entry_fee_en": "Free admission (Donations welcome)",
    "entry_fee_ta": "இலவச அனுமதி",
    "nearest_station": "Madurai Junction (MDU)",
    "nearest_airport": "Madurai International Airport (IXM) - 12 km",
    "image_url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Meenakshi_Amman_West_Tower.jpg/960px-Meenakshi_Amman_West_Tower.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail",
    "image_source_name": "Wikimedia Commons / Madurai",
    "image_source_url": "https://en.wikipedia.org/wiki/Madurai",
