    "short_desc_en": "The First of the Six Abodes (Arupadaiveedu) of Lord Murugan, carved into rock by 8th-century Pandya kings.",
    "short_desc_ta": "முருகப் பெருமானின் அறுபடை வீடுகளில் முதலாவது படைவீடான 8-ஆம் நூற்றாண்டு பாண்டியர் கால குடைவரைக் கோவில்.",
    "description_en": "Celebrated as the sacred site where Lord Murugan married Deivayanai, Thiruparankundram features an extraordinary rock-cut sanctum carved into the granite hill during the reign of Pandya King Maravarman Sundara Pandyan. It features rock-cut shrines to Shiva, Vishnu, Durga, and Ganesha.",
    "description_ta": "முருகப் பெருமான் தெய்வானையை மணம் புரிந்த தலமாக போற்றப்படும் திருப்பரங்குன்றம், மலையைக் குடைந்து அமைக்கப்பட்ட அற்புதமான குடைவரை சிற்பங்களைக் கொண்ட முதல் படைவீடாகும்.",
