    "short_desc_ta": "1645-ல் மன்னர் திருமலை நாயக்கரால் கட்டப்பட்ட 16 ஏக்கர் பரப்பளவிலான பிரம்மாண்ட வரலாற்று தெப்பக்குளம்.",
    "description_en": "Constructed by King Thirumalai Nayak, this is one of the largest temple tanks in South India measuring 1,000 feet by 950 feet. It features an island in the center with a mandapam called the Maiya Mandapam (Central Pavilion) and a Vinayakar temple, supplied by underground water channels from the Vaigai River.",
    "description_ta": "தென்னிந்தியாவின் மிகப்பெரிய தெப்பக்குளங்களில் ஒன்றான இது, வைகை நதியிலிருந்து நிலத்தடி கால்வாய்கள் மூலம் நீர் பெறும் வகையில் அமைக்கப்பட்டுள்ளது. இதன் நடுவே மைய மண்டபம் மற்றும் நந்தவனம் அமைந்துள்ளது.",
