    "description_en": "Developed in a natural ravine at an altitude of 1,780 meters, Sim’s Park features landscaped terraces, winding footpaths, and over 1,000 species of exotic trees, ornamental plants, and flowering shrubs including Rudraksha, Queensland Karry Pine, and paper bark trees.",
    "description_ta": "கடல் மட்டத்திலிருந்து 1,780 மீட்டர் உயரத்தில் அமைந்துள்ள சிம்ஸ் பூங்காவில் ருத்ராட்ச மரம், ஆஸ்திரேலியன் பைன் உள்ளிட்ட உலகின் பல நாடுகளைச் சேர்ந்த 1000-க்கும் மேற்பட்ட அரிய வகை தாவரங்கள் பாதுகாக்கப்படுகின்றன.",
