    "short_desc_en": "Scenic sacred river of the Toda tribe featuring twin cascading waterfalls and motorboat rides.",
    "short_desc_ta": "தோடர் பழங்குடியினரின் புனித நதியான பைகாரா ஆற்றின் கம்பீரமான இரட்டை நீர்வீழ்ச்சி மற்றும் படகு இல்லம்.",
    "description_en": "Originating from Mukurthi Peak, the Pykara River flows over rolling grassy meadows before tumbling down two cascading falls of 55 meters and 61 meters over granite rocks. The adjacent TTDC boat house offers speedboating amidst pristine shola forests.",
    "description_ta": "முகுர்த்தி மலையில் உருவாகும் பைகாரா நதி, 55 மற்றும் 61 மீட்டர் உயரங்களிலிருந்து பாறைகளில் பாய்ந்து இறங்கும் இரட்டை நீர்வீழ்ச்சியாக காட்சியளிக்கிறது. இங்கு TTDC நடத்தும் படகு சவாரி மிகவும் புகழ்பெற்றது.",
