    "name_en": "Mudumalai Tiger Reserve & Theppakadu Elephant Camp",
    "name_ta": "முதுமலை புலிகள் காப்பகம் மற்றும் தெப்பக்காடு யானைகள் முகாம்",
    "category": "Wildlife",
    "category_ta": "வனவிலங்கு சரணாலயம்",
    "short_desc_en": "First wildlife sanctuary in South India established in 1940 and designated Tiger Reserve in Nilgiri Biosphere.",
    "short_desc_ta": "1940-ல் உருவாக்கப்பட்ட தென்னிந்தியாவின் முதல் வனவிலங்கு சரணாலயம் மற்றும் யுனெஸ்கோ நீலகிரி உயிர்க்கோள பகுதி.",
    "description_en": "Spanning 321 sq km bordering Karnataka and Kerala, Mudumalai is a critical wildlife corridor protecting Bengal tigers, Asian elephants, Indian leopards, and dholes. The Theppakadu Elephant Camp here is the oldest elephant camp in Asia established in 1927.",
    "description_ta": "321 சதுர கி.மீ பரப்பளவில் கர்நாடகா மற்றும் கேரள எல்லைகளில் பரந்து விரிந்துள்ள முதுமலை, புலிகள், காட்டு யானைகள், சிறுத்தைகள் மற்றும் அரிய பறவைகளின் புகலிடமாகும். இங்குள்ள தெப்பக்காடு யானைகள் முகாம் ஆசியாவின் மிகப் பழமையான முகாம்களில் ஒன்றாகும்.",
    "latitude": 11.5833,
    "longitude": 76.5333,
    "address_en": "Theppakadu, Gudalur-Ooty Highway, The Nilgiris District - 643211",
    "address_ta": "தெப்பக்காடு, கூடலூர்-ஊட்டி சாலை, நீலகிரி மாவட்டம் - 643211",
    "timings_en": "Safari: 06:30 AM – 09:00 AM, 03:30 PM – 06:00 PM; Elephant Camp: 08:30 AM – 09:00 AM, 05:30 PM – 06:00 PM",
    "timings_ta": "சஃபாரி: காலை 06:30 – 09:00, மாலை 03:30 – 06:00; யானைகள் முகாம்: காலை 08:30 – 09:00, மாலை 05:30 – 06:00",
    "best_time_to_visit_en": "October to May",
    "best_time_to_visit_ta": "அக்டோபர் முதல் மே வரை",
    "entry_fee_en": "Entry: ₹30; Bus Safari: ₹350 per person; Elephant Camp: ₹30 (Forest Dept)",
