    "name_en": "Nilgiri Mountain Railway (Toy Train)",
    "name_ta": "நீலகிரி மலை ரயில் (யுனெஸ்கோ உலக பாரம்பரிய சின்னம்)",
    "category": "Heritage",
    "category_ta": "பாரம்பரியம்",
    "short_desc_en": "UNESCO World Heritage 46-km metre-gauge cogwheel rack railway built by British in 1908 from Mettupalayam to Ooty.",
    "short_desc_ta": "1908-ல் பிரிட்டிஷாரால் உருவாக்கப்பட்ட 46 கி.மீ நீள யுனெஸ்கோ உலக பாரம்பரிய மலை ரயில் பாதை.",
    "description_en": "The Nilgiri Mountain Railway is the only rack railway in India using the Abt rack and pinion system to scale steep mountain grades between Mettupalayam (326m) and Ooty (2,203m). Passing through 16 tunnels, 250 bridges, and lush valleys, it provides an unforgettable journey.",
    "description_ta": "மேட்டுப்பாளையத்திலிருந்து குன்னூர் வழியாக ஊட்டி வரை செல்லும் இந்த மலை ரயில், 16 சுரங்கப் பாதைகள் மற்றும் 250 பாலங்கள் வழியாக இயற்கை எழில் கொஞ்சும் மலை முகடுகளில் தவழ்ந்து செல்லும் உலகப் புகழ்பெற்ற ரயிலாகும்.",
    "latitude": 11.4064,
