    "address_en": "Udhagamandalam Railway Station, Ooty, The Nilgiris District - 643001",
    "address_ta": "உதகமண்டலம் ரயில் நிலையம், ஊட்டி, நீலகிரி மாவட்டம் - 643001",
    "timings_en": "Daily scheduled departures from Mettupalayam & Ooty (Southern Railway)",
    "timings_ta": "தினசரி கால அட்டவணைப்படி இயங்கும் (தெற்கு ரயில்வே)",
    "best_time_to_visit_en": "Throughout the year",
