    "entry_fee_en": "Second Class: ₹35 – ₹50; First Class: ₹205 – ₹600 (IRCTC booking)",
    "entry_fee_ta": "ரயில்வே கட்டணம்: ₹35 முதல் ₹600 வரை (IRCTC மூலம் முன்பதிவு)",
