    "description_en": "Cape Comorin is the unique geographical point on Earth where one can watch sunrise and sunset from the same beach, especially breathtaking on Chitra Pournami when sun setting and full moon rising can be viewed simultaneously on opposite horizons.",
    "description_ta": "ஒரே இடத்தில் நின்றபடி சூரிய உதயம் மற்றும் சூரிய அஸ்தமனத்தைக் காணக்கூடிய உலகின் அரிய புவியியல் முனை இதுவாகும். சித்ரா பவுர்ணமி நாளில் ஒரே நேரத்தில் சூரிய அஸ்தமனமும் சந்திர உதயமும் தெரிவது தனித்துவமான நிகழ்வாகும்.",
