    "category_ta": "பாரம்பரியம்",
    "short_desc_en": "Longest and highest aqueduct bridge in Asia, constructed in 1966 across the Pahrali River valley.",
    "short_desc_ta": "1966-ல் பஹ்ருளி ஆற்றின் குறுக்கே கட்டப்பட்ட ஆசியாவின் மிக நீளமான மற்றும் உயரமான தொட்டிப் பாலம்.",
    "description_en": "Constructed during the Chief Ministership of K. Kamaraj as a drought-relief irrigation channel, the bridge measures 1,240 feet in length and stands on 28 colossal pillars at a height of 115 feet above the river valley offering panoramic vistas of Western Ghats hills and coconut plantations.",
    "description_ta": "கர்மவீரர் காமராஜர் ஆட்சிக் காலத்தில் விவசாய பாசனத்திற்காக உருவாக்கப்பட்ட இந்த பாலம், 115 அடி உயரத்தில் 28 பிரம்மாண்ட தூண்களுடன் 1,240 அடி நீளத்திற்கு பள்ளத்தாக்கின் மேலே கம்பீரமாக நிற்கிறது.",
    "latitude": 8.3361,
