    "name_ta": "திற்ப்பரப்பு நீர்வீழ்ச்சி மற்றும் மகாதேவர் கோவில்",
    "category": "Waterfall",
    "category_ta": "நீர்வீழ்ச்சி",
    "short_desc_en": "Spectacular 50-foot multi-tiered waterfall on the Kodayar River adjacent to a 9th-century Shiva temple.",
    "short_desc_ta": "கோதையாற்றின் மீது 300 அடி அகலத்தில் 50 அடி உயரத்திலிருந்து ஆர்ப்பரித்துக் கொட்டும் இயற்கை நீர்வீழ்ச்சி.",
    "description_en": "Formed by the Kodayar River descending over a rocky bed extending about 300 feet in length, Thirparappu waterfalls features swimming pools and TTDC boat rides. Right next to the falls is an ancient 9th-century rock-cut Shiva temple with historic Vatteluttu inscriptions.",
    "description_ta": "பாறைப் படுகையில் 300 அடி அகலத்திற்குப் பரந்து பாய்ந்து விழும் திற்ப்பரப்பு நீர்வீழ்ச்சி, பாதுகாப்பான குளியல் தொட்டிகள் மற்றும் சிறுவர் பூங்காவைக் கொண்டுள்ளது. இதன் அருகில் 9-ஆம் நூற்றாண்டு மகாதேவர் கோவில் அமைந்துள்ளது.",
