    "name_ta": "சுசீந்திரம் அருள்மிகு தாணுமாலயன் திருக்கோவில்",
    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Historic 9th-century temple representing the Trimurti (Brahma, Vishnu, Shiva in a single lingam) with musical pillars.",
    "short_desc_ta": "மும்மூர்த்திகளும் (சிவன், விஷ்ணு, பிரம்மா) ஒரே லிங்கத்தில் தாணுமாலயனாகக் காட்சி தரும் இசைத்தூண்கள் கொண்ட அற்புதக் கோவில்.",
    "description_en": "Suchindram Temple is renowned for its 134-foot gopuram decorated with mythological carvings, four musical stone pillars cut out of a single granite rock producing musical notes when tapped, and a colossal 22-foot monolithic statue of Lord Hanuman.",
    "description_ta": "134 அடி உயர ராஜகோபுரம், தட்டினால் ஏழு சுரங்களை எழுப்பும் ஒற்றைக்கல் இசைத் தூண்கள் மற்றும் 22 அடி உயர விஸ்வரூப ஆஞ்சநேயர் சிலையுடன் கூடிய வரலாற்று சிறப்புமிக்க திருக்கோவில்.",
