    "category_ta": "பாரம்பரியம்",
    "short_desc_en": "Unique 8-story hexagonal coastal victory tower built in 1814 by Maratha King Serfoji II overlooking Palk Strait.",
    "short_desc_ta": "1814-ல் மராட்டிய மன்னர் இரண்டாம் சரபோஜியால் பாக்கு நீரிணை கடற்கரையில் கட்டப்பட்ட எண்கோண 8 அடுக்கு கோட்டை.",
    "description_en": "Standing 75 feet tall right on the seashore of the Bay of Bengal, Manora Fort was erected by Raja Serfoji II to commemorate the British victory over Napoleon Bonaparte at Waterloo in 1815. It features a moat, arched ramparts, and a spiral staircase to panoramic sea views.",
    "description_ta": "நெப்போலியனை வீழ்த்திய நினைவாக 1814-ல் இரண்டாம் சரபோஜி மன்னரால் கட்டப்பட்ட 75 அடி உயரமுள்ள 8 அடுக்கு எண்கோண வடிவ வரலாற்றுச் சின்னம் இதுவாகும்.",
