    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Renowned 17th-century historic temple patronized by the Thanjavur Maratha kings, where the deity is composed of anthill clay.",
    "short_desc_ta": "தஞ்சை மராட்டிய மன்னர்களால் போற்றி பாதுகாக்கப்பட்ட, புற்று மண்ணால் உருவான மாரியம்மன் அருள் பாலிக்கும் சக்தி பீடம்.",
    "description_en": "Constructed around 1680 CE by Maratha King Venkoji Maharaja following a divine vision, the main deity here is an unbaked clay murti upon which sacred thailabhishekam is performed once every five years. Saint Sadhasiva Brahmendral installed the sacred Sri Chakra in the sanctum.",
    "description_ta": "1680-ல் வெங்கோஜி மகாராஜாவால் கட்டப்பட்ட இக்கோவிலில் ஸ்ரீ சதாசிவ பிரமேந்திராள் ஸ்ரீ சக்கர பிரதிஷ்டை செய்துள்ளார். ஆவணி ஞாயிற்றுக்கிழமைகளில் லட்சக்கணக்கான பக்தர்கள் கூடுகின்றனர்.",
