    "description_en": "Constructed by British engineer Sir Arthur Cotton modeling the ancient Kallanai, Mukkombu bifurcates the Cauvery River into the Kollidam (Coleroon) and Cauvery. The extensive riverside park features pedal boating, children’s play areas, and lush gardens.",
    "description_ta": "கல்லணையின் வடிவமைப்பை மாதிரியாகக் கொண்டு கட்டப்பட்ட முக்கொம்பு அணை, காவிரியும் கொள்ளிடமும் பிரியும் அழகிய முக்கோணப் பகுதியில் அமைந்துள்ள சிறந்த சுற்றுலா மையமாகும்.",
