    "description_ta": "தமிழ்நாடு வனத்துறையால் ஸ்ரீரங்கத்தில் காவிரி ஆற்றங்கரையில் உருவாக்கப்பட்ட இந்த சுற்றுச்சூழல் பூங்காவில், நட்சத்திர வனம், நீர்வீழ்ச்சிகள் மற்றும் அரிய வகை பட்டாம்பூச்சிகளின் இயற்கை வாழிடம் அமைக்கப்பட்டுள்ளது.",
