    "short_desc_en": "Sacred waterfalls and reservoir on the Perennial Thamirabarani River in the Western Ghats.",
    "short_desc_ta": "வற்றாத தாமிரபரணி ஆற்றின் பிறப்பிடமாகத் திகழும் மேற்குத் தொடர்ச்சி மலையின் புனித அகஸ்தியர் அருவி.",
    "description_en": "Legend says Sage Agastya witnessed the cosmic wedding of Shiva and Parvati at this spot. The Thamirabarani River plunges down from a height of 100 feet over rock steps at Agasthiyar Falls, while the upstream Papanasam Dam is surrounded by rainforest peaks.",
    "description_ta": "அகத்திய முனிவருக்கு சிவபெருமான் திருமணக் காட்சி தந்த புண்ணிய தலமான பாபநாசத்தில், 100 அடி உயரத்திலிருந்து மூலிகை குணம் கொண்ட தாமிரபரணி நதி அருவியாகக் கொட்டுகிறது.",
