    "short_desc_ta": "895 சதுர கி.மீ பரப்பளவில் 14 நதிகள் உருவாகும் தென்னிந்தியாவின் வற்றாத நதிகள் சரணாலயம்.",
    "description_en": "Part of the Agasthyamalai Biosphere Reserve, KMTR protects pristine wet evergreen rainforests, endangered Lion-tailed Macaques, Bengal tigers, and Nilgiri Tahrs. The scenic Manjolai tea estates sit at 1,162 meters nestled deep within the reserve.",
