    "short_desc_en": "Built in 1440 CE by Pandyan King Parakkirama Pandian, famed for its towering 178-foot Rajagopuram.",
    "short_desc_ta": "1440-ல் பராக்கிரம பாண்டிய மன்னரால் கட்டப்பட்ட 178 அடி உயர பிரம்மாண்ட ராஜகோபுரம் கொண்ட \"தெற்கின் காசி\".",
    "description_en": "Known as the Varanasi of the South, this historic temple was commissioned by King Parakkirama Pandian after a divine dream. It features musical pillars, exquisite stone sculptures, and a high breeze-catching 178-ft gopuram offering panoramic views of the Western Ghats.",
    "description_ta": "வடக்கு காசிக்கு செல்ல முடியாத தென்னக மக்களுக்காக பராக்கிரம பாண்டியரால் உருவாக்கப்பட்ட தென்காசி கோவில், நுணுக்கமான சிற்பங்கள் மற்றும் இசைத்தூண்களுக்கு பெயர் பெற்றது.",
