    "id": "dgl-pillar-rocks-kodaikanal",
    "district_id": "dindigul",
    "district_name_en": "Dindigul",
    "district_name_ta": "திண்டுக்கல்",
    "name_en": "Pillar Rocks & Coaker’s Walk, Kodaikanal",
    "name_ta": "பில்லர் ராக்ஸ் (தூண் பாறைகள்) மற்றும் கோக்கர்ஸ் வாக்",
    "category": "Hill Station",
    "category_ta": "மலை வாஸ்தலம்",
    "short_desc_en": "Three giant granite monolith boulders standing 122 meters (400 ft) high vertically amidst mist and valleys.",
    "short_desc_ta": "பனி மூட்டத்திற்கு இடையே 122 மீட்டர் உயரத்தில் செங்குத்தாக நிற்கும் மூன்று பிரம்மாண்ட தூண் பாறைகள்.",
    "description_en": "Managed by the Tamil Nadu Tourism Department, Pillar Rocks offer dramatic views of three massive vertical granite cliffs dropping into fathomless gorges. The nearby Coaker’s Walk provides a 1-km paved pedestrian trail along mountain cliffs with sweeping valley views.",
    "description_ta": "கொடைக்கானலின் மிக முக்கிய இயற்கை அடையாளமான தூண் பாறைகள் 400 அடி ஆழ பள்ளத்தாக்கை நோக்கி கம்பீரமாக நிற்கின்றன. அருகிலுள்ள கோக்கர்ஸ் வாக் அழகிய பள்ளத்தாக்கு காட்சிகளை வழங்குகிறது.",
