    "short_desc_ta": "16-ஆம் நூற்றாண்டில் முத்து கிருஷ்ணப்ப நாயக்கரால் கட்டப்பட்டு திப்பு சுல்தானால் பலப்படுத்தப்பட்ட வரலாற்று மலைக்கோட்டை.",
    "description_en": "Rising 280 feet above the plains on a colossal monolithic rock resembling a pillow (dindu), this ASI-protected monument was a pivotal military stronghold during the Carnatic Wars and Anglo-Mysore Wars, equipped with cannons, ammunition vaults, and a historic Shiva temple.",
