    "short_desc_ta": "1,411 சதுர கி.மீ பரப்பளவுடன் கிழக்கு மற்றும் மேற்குத் தொடர்ச்சி மலைகளை இணைக்கும் மிகப்பெரிய புலிகள் காப்பகம்.",
    "description_en": "Honored with the international TX2 award for doubling its tiger population, STR forms an indispensable wildlife corridor for over 80 Bengal tigers, 1,000 Asian elephants, leopards, black panthers, and vultures.",
