    "short_desc_ta": "100 கால் மண்டபம், அத்தி வரதர் பெருவிழா புகழ் பெற்ற 108 வைணவ திவ்ய தேசங்களின் முதன்மைத் தலம்.",
    "description_en": "Spread across a massive 23-acre complex, this temple was expanded by the Cholas and Vijayanagara emperors. It is celebrated for its intricate monolithic chains carved out of granite and the Athi Varadar wooden murti immersed in the temple tank and brought out only once every 40 years.",
    "description_ta": "23 ஏக்கர் பரப்பளவில் அமைந்துள்ள இத்திருக்கோவில், நுணுக்கமான சிற்ப வேலைப்பாடுகளுடன் கூடிய 100 கால் மண்டபம் மற்றும் 40 ஆண்டுகளுக்கு ஒருமுறை நடைபெறும் அத்திவரதர் வைபவத்திற்கு உலகப் புகழ் பெற்றது.",
