    "description_en": "Located in the historic center of Kanchipuram, Kamakshi Amman Temple is one of the most prominent shrines dedicated to the Goddess in India. The Goddess is seated in the majestic Padmasana posture holding sugarcane bow and arrows of flowers. The golden vimana above the sanctum gleams brilliantly.",
