    "short_desc_ta": "1914-ல் திறக்கப்பட்ட இந்தியாவின் முதல் 2.06 கி.மீ நீள வரலாற்றுச் சிறப்புமிக்க கடல் ரயில் பாலம்.",
    "description_en": "Opened in 1914, the Pamban Railway Bridge spans the turbulent waters of the Palk Strait on 143 concrete piers with a central Scherzer rolling lift span that opens to allow ships to pass beneath. The parallel road bridge (Annai Indira Gandhi Bridge) offers panoramic views of the turquoise sea and islands.",
    "description_ta": "143 தூண்களுடன் 2.06 கி.மீ தொலைவுக்கு கடலின் மேல் அமைக்கப்பட்டுள்ள இந்த அதிசயப் பாலம், கப்பல்கள் செல்ல நடுவே திறந்து மூடும் தூக்குப்பால அமைப்பைக் கொண்டுள்ளது.",
