    "category_ta": "கடற்கரை",
    "short_desc_en": "Ghost town submerged in the 1964 cyclone, marking the southernmost tip of Rameswaram overlooking Sri Lanka.",
    "short_desc_ta": "1964 புயலால் அழிந்த வரலாற்று நகரம் மற்றும் இந்திய எல்லையின் அரிச்சல் முனை சங்கமக் கடற்கரை.",
    "description_en": "Dhanushkodi was destroyed in the 1964 super cyclone and left as a frozen-in-time ghost town with haunting ruins of its railway station, church, temple, and customs office. At Arichal Munai (Land’s End), just 18 miles from Sri Lanka, the tranquil waters of the Bay of Bengal meet the rough waves of the Indian Ocean.",
    "description_ta": "வங்கக் கடலும் இந்தியப் பெருங்கடலும் சங்கமிக்கும் அரிச்சல் முனையில் இந்தியாவின் எல்லை முடிகிறது. 1964 புயலின் நினைவுகளாக எஞ்சியிருக்கும் தேவாலயம் மற்றும் ரயில் நிலைய இடிபாடுகள் அரிய சுற்றுலா அனுபவமாகும்.",
