    "short_desc_ta": "செங்குத்தான மலை உச்சியிலிருந்து வற்றாமல் ஊற்றெடுக்கும் ஐந்து புனித தீர்த்தங்கள் கொண்ட சோழர் கால திருத்தலம்.",
    "description_en": "Perched on the Theerthamalai hill at 1,000 meters above sea level, this ancient temple dedicated to Lord Shiva was worshipped by Chola and Vijayanagara monarchs. Water flows perennially from five rocky springs: Agasthya Theertham, Rama Theertham, Agni Theertham, Kumara Theertham, and Gauri Theertham.",
    "description_ta": "அகஸ்திய தீர்த்தம், ராம தீர்த்தம் உள்ளிட்ட ஐந்து வற்றாத மூலிகை நீரூற்றுகள் பாறைகளிலிருந்து வெளிவரும் தீர்த்தமலை கோவில், பக்திக்கும் மலையேற்றத்திற்கும் உகந்த தலமாகும்.",
