    "category": "Heritage",
    "category_ta": "பாரம்பரியம்",
    "short_desc_en": "Strategic 18th-century massive hill fortress defended during Anglo-Mysore Wars by Hyder Ali and Tipu Sultan.",
    "short_desc_ta": "திப்பு சுல்தான் மற்றும் ஹைதர் அலி காலத்தில் போர்த்தளமாக விளங்கிய வரலாற்று சிறப்புமிக்க மலைக்கோட்டை.",
    "description_en": "Standing on a steep granite outcrop at an altitude of 3,200 feet, Rayakottai is an ASI-protected monument that served as a key border fortress of Mysore Kingdom. It features subterranean ammunition vaults, natural water tanks, and ramparts with sweeping views of Krishnagiri plains.",
    "description_ta": "3,200 அடி உயரத்தில் அமைந்துள்ள ராயக்கோட்டை, ஆங்கிலேய-மைசூர் போர்களில் முக்கிய கேந்திரமாக விளங்கியது. இதன் கோட்டை சுவர்கள் மற்றும் இயற்கை குகைகள் தொல்லியல் துறையால் பாதுகாக்கப்படுகின்றன.",
    "latitude": 12.5167,
