    "name_ta": "அவிநாசி அருள்மிகு அவிநாசிலிங்கேஸ்வரர் திருக்கோவில்",
    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Ancient Paadal Petra Sthalam praised by Sundarar (Muthalai Vayil Pillai miracle), with a 100-foot Rajagopuram.",
    "short_desc_ta": "சுந்தரமூர்த்தி நாயனாரால் முதலை விழுங்கிய குழந்தையை மீட்டெடுத்த வரலாற்றுச் சிறப்புமிக்க தேவாரத் திருத்தலம்.",
    "description_en": "Dating to the 10th century Chola and Hoysala periods, Avinashilingeswarar Temple features magnificent stone sculptures, seven tiers in its Rajagopuram, and the revered Karunambikai Amman shrine. It is the site of one of the largest temple car (ther) festivals in Tamil Nadu.",
    "description_ta": "100 அடி உயர ராஜகோபுரம் மற்றும் நுணுக்கமான சிற்பங்களைக் கொண்ட அவிநாசி கோவில், கொங்கு மண்டலத்தின் மிக முக்கியமான ஆன்மீகத் தலமாகும். இங்குள்ள சித்திரைத் தேரோட்டம் உலகப் புகழ்பெற்றது.",
