    "short_desc_ta": "1,200 படிகள் கொண்ட மலை உச்சியில் சிவபெருமான் மாதொருபாகனாக (அர்த்தநாரீஸ்வரராக) காட்சி தரும் அரிய திருத்தலம்.",
    "description_en": "Perched on the Nagagiri Hill (serpent-shaped red rock) at an elevation of 1,900 feet, this is one of the rare temples in the world dedicated to the Ardhanareeswara form (half Shiva, half Parvati). It features an extraordinary 60-foot rock snake sculpture carved along the path.",
    "description_ta": "சிவபெருமானும் பார்வதி தேவியும் சரிபாதியாக இணைந்து காட்சி தரும் உலகப் புகழ்பெற்ற இத்திருக்கோவிலில், மலையைச் சுற்றி வடிக்கப்பட்டுள்ள 60 அடி நீள பாம்புச் சிற்பம் வியக்கத்தக்கது.",
