    "id": "svg-pillayarpatti-temple",
    "district_id": "sivaganga",
    "district_name_en": "Sivaganga",
    "district_name_ta": "சிவகங்கை",
    "name_en": "Arulmigu Karpaga Vinayagar Temple, Pillayarpatti",
    "name_ta": "பிள்ளையார்பட்டி அருள்மிகு கற்பக விநாயகர் திருக்கோவில்",
    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Famous 1,600-year-old rock-cut cave temple carving of Lord Ganesha with six-foot bas-relief relief.",
    "short_desc_ta": "1,600 ஆண்டுகள் பழமையான மலையைக் குடைந்து வடிக்கப்பட்ட 6 அடி உயர ஒற்றைக்கல் கற்பக விநாயகர் குடைவரை கோவில்.",
    "description_en": "Carved out of a natural hill during the Early Pandya era (4th–5th century CE), this sacred shrine features a six-foot bas-relief of Lord Ganesha with two arms holding a modak, turned to the right (Valampuri Vinayagar). Ancient Tamil-Brahmi and Vatteluttu inscriptions adorn the cave.",
    "description_ta": "ஆரம்பகால பாண்டியர் காலத்தில் 1,600 ஆண்டுகளுக்கு முன் மலையைக் குடைந்து உருவாக்கப்பட்ட இந்த வலம்புரி விநாயகர் குடைவரைக் கோவில், தமிழகத்தின் தலைசிறந்த விநாயகர் திருத்தலமாகும்.",
    "latitude": 10.1206,
    "longitude": 78.6739,
    "address_en": "Pillayarpatti, Thirupathur Taluk, Sivaganga District - 630207",
    "address_ta": "பிள்ளையார்பட்டி, திருப்பத்தூர் வட்டம், சிவகங்கை மாவட்டம் - 630207",
    "timings_en": "06:00 AM – 01:00 PM, 04:00 PM – 08:30 PM",
