    "description_en": "Covering 38.4 hectares encompassing Periya Kollukudi, Chinna Kollukudi, and Vettangudi tanks, this sanctuary is populated with babul (Acacia nilotica) trees providing safe nesting canopies for over 8,000 birds including openbill storks, white ibis, and night herons.",
    "description_ta": "38.4 ஹெக்டேர் பரப்பளவில் அமைந்துள்ள வெட்டங்குடி சரணாலயத்தில், கருவேல மரங்களின் கிளைகளில் பல்லாயிரக்கணக்கான நாரைகள், கூழைக்கடாக்கள் தங்கி கூடுகட்டி குஞ்சு பொரிக்கின்றன.",
