    "short_desc_ta": "207 படிகள் கொண்ட அழகிய மலைக்கோவிலைச் சுற்றி நூற்றுக்கணக்கான தேசியப் பறவையான மயில்கள் வாழும் சரணாலயம்.",
    "description_en": "Viralimalai is famous for its hilltop temple dedicated to Lord Murugan where saint Arunagirinathar composed celebrated Tiruppugazh hymns. The surrounding woodlands have been designated a wildlife sanctuary dedicated to the conservation of India’s national bird, the Indian peafowl.",
    "description_ta": "அருணகிரிநாதரால் திருப்புகழ் பாடப்பெற்ற விராலிமலை முருகன் கோவிலின் சுற்றுப்புறக் காடுகளில், தேசியப் பறவையான மயில்கள் இயல்பாக உலவி வரும் இயற்கை சரணாலயம் அமைந்துள்ளது.",
