    "short_desc_ta": "உருவமற்ற இறைவனை (அரூப லிங்கம்) வழிபடும் அரிய தத்துவமும் அற்புத கற்பனை சிற்பங்களும் கொண்ட தலம்.",
    "description_en": "Associated with Saint Manikkavacakar who composed the Tiruvacakam here, the temple is an architectural marvel. Uniquely, there is no lingam, Nandi, or Chandikeswara in the sanctum; instead, worshippers pay homage to the formless supreme spirit on an altar.",
    "description_ta": "மாணிக்கவாசகர் திருவாசகம் பாடி முக்தி பெற்ற திருப்பெருந்துறையான இத்திருக்கோவிலில், கருவறையில் உருவ வழிபாடு இல்லாமல் ஆவுடையார் பீடம் மட்டுமே வழிபடப்படும் தத்துவச் சிறப்பு உள்ளது.",
