    "name_ta": "வைகை அணை மற்றும் மின்னொளி பூங்கா, ஆண்டிபட்டி",
    "category": "Water Body",
    "category_ta": "நீர்நிலைகள்",
    "short_desc_en": "Massive 111-foot reservoir built across the Vaigai River in 1959, with children’s amusement and musical fountain.",
    "short_desc_ta": "1959-ல் காமராஜர் ஆட்சியில் கட்டப்பட்ட 111 அடி உயர வைகை அணை மற்றும் அழகிய பூங்கா.",
    "description_en": "Opened in 1959 by Chief Minister K. Kamaraj, the Vaigai Dam stores 6,143 million cubic feet of water irrigating five southern districts. Its landscaped garden on both banks features dancing musical fountains, boating, and vibrant nighttime illumination on weekends.",
    "description_ta": "தென் மாவட்டங்களின் பாசன ஆதாரமாகத் திகழும் வைகை அணை, வார இறுதி நாட்களில் மின்னொளி அலங்காரத்துடனும் இசை நீரூற்றுடனும் சுற்றுலாப் பயணிகளுக்கு சிறப்பான விருந்தாக அமைகிறது.",
    "latitude": 10.0547,
    "longitude": 77.5897,
    "address_en": "Vaigai Dam, Andipatti Taluk, Theni District - 625562",
