    "short_desc_ta": "கொடைக்கானல் மலை முகடுகளிலிருந்து பாம்பாறு மூலமாக செதுக்கப்பட்ட பாறைகளில் பாய்ந்து இறங்கும் எழில் அருவி.",
    "description_en": "Located 8 km from Periyakulam at the base of the Kodaikanal hills, Kumbakkarai Falls cascades in two tiers over smooth granite rocks creating natural rock pools where tourists enjoy refreshing mineral-rich bathing in pristine forest surroundings.",
