    "name_en": "Manapad Coastal Dunes & Holy Cross Church",
    "name_ta": "மணப்பாடு மணற்குன்று கடற்கரை மற்றும் திருச்சிலுவை திருத்தலம்",
    "category": "Beach",
    "category_ta": "கடற்கரை",
    "short_desc_en": "Historic 1540 coastal promontory with towering sand dunes where St. Francis Xavier resided in a natural cave.",
    "short_desc_ta": "1540-ல் புனித பிரான்சிஸ் சேவியர் தங்கிய குகை மற்றும் இயற்கை மணற்குன்றுகளுடன் கூடிய எழில்மிகு கடற்கரை.",
    "description_en": "Often called the \"Goa of Tamil Nadu,\" Manapad is a natural coastal promontory framed by 200-foot sandy dunes and turquoise waters of the Gulf of Mannar. St. Francis Xavier lived in a natural rock cave here in 1542, and the Holy Cross Church holds a relic of the True Cross of Jerusalem.",
    "description_ta": "வங்கக் கடலும் மன்னார் வளைகுடாவும் சந்திக்கும் மணப்பாடு, இயற்கை மணல் குன்றுகளும், 400 ஆண்டுகள் பழமையான திருச்சிலுவை ஆலயமும் கொண்ட உலகப் புகழ்பெற்ற சர்ஃபிங் மற்றும் ஆன்மீக தலமாகும்.",
