    "id": "tho-kalugumalai-vettuvan-koil",
    "district_id": "thoothukudi",
    "district_name_en": "Thoothukudi",
    "district_name_ta": "தூத்துக்குடி",
    "name_en": "Kalugumalai Monolithic Vettuvan Koil & Jain Beds",
    "name_ta": "கழுகுமலை வெட்டுவான் கோவில் மற்றும் சமணர் குகைப் படுக்கைகள்",
    "category": "Heritage",
    "category_ta": "பாரம்பரியம்",
    "short_desc_en": "The \"Ellora of the South\" – an 8th-century monolithic rock-cut temple carved from top to bottom by Pandya artisans.",
    "short_desc_ta": "பாண்டிய மன்னர்களால் மலையின் மேலிருந்து கீழாக குடைந்து செதுக்கப்பட்ட \"தென்னகத்தின் எல்லோரா\" வெட்டுவான் கோவில்.",
    "description_en": "Vettuvan Koil is an unfinished monolithic rock-cut shrine carved out of a single huge granite cliff by Pandya artisans in the 8th century, showcasing masterly depictions of Dakshinamurthy and Gandharvas. The adjoining cliff face bears over 100 Jain tirthankara bas-relief sculptures with Vatteluttu inscriptions.",
    "description_ta": "ஒற்றைப் பாறையில் மேலிருந்து கீழாக குடைந்து அமைக்கப்பட்ட வெட்டுவான் கோவிலும், அதன் அருகில் பாறையில் வடிக்கப்பட்டுள்ள 100-க்கும் மேற்பட்ட சமணர் தீர்த்தங்கரர் புடைப்புச் சிற்பங்களும் தொல்லியல் துறையால் பாதுகாக்கப்படும் கலைப் பொக்கிஷங்கள்.",
    "latitude": 9.1458,
    "longitude": 77.7083,
    "address_en": "Kalugumalai, Kovilpatti Taluk, Thoothukudi District - 628552",
    "address_ta": "கழுகுமலை, கோவில்பட்டி வட்டம், தூத்துக்குடி மாவட்டம் - 628552",
    "timings_en": "06:00 AM – 06:00 PM (Daily)",
