    "best_time_to_visit_ta": "அக்டோபர் முதல் மார்ச் வரை",
    "entry_fee_en": "Free admission (ASI Protected Monument)",
    "entry_fee_ta": "இலவச அனுமதி (தொல்லியல் துறை)",
    "nearest_station": "Thoothukudi (TN) / Tiruchendur (TCN)",
