    "district_name_ta": "திருவாரூர்",
    "name_en": "Muthupet Mangrove Forest & Lagoon Eco-Tourism",
    "name_ta": "முத்துப்பேட்டை அலையாத்தி காடுகள் மற்றும் உப்பங்கழி",
    "category": "Nature",
    "category_ta": "இயற்கை எழில்",
    "short_desc_en": "Largest mangrove wetland in Tamil Nadu covering 120 sq km with elevated wooden boardwalks and boat rides.",
    "short_desc_ta": "120 சதுர கி.மீ பரப்பளவில் அமைந்துள்ள தமிழ்நாட்டின் மிகப்பெரிய மாங்குரோவ் அலையாத்தி காடுகள்.",
    "description_en": "Situated at the southern end of the Cauvery delta where the Paminiyar, Koraiyar, and Kilaithangiyar rivers meet the Palk Strait, Muthupet features dense Rhizophora mangroves, a 162-meter wooden observation canopy walk, and boat safaris to spot migrating flamingos and pelicans.",
    "description_ta": "காவிரி டெல்டாவின் 5 ஆறுகள் கடலில் கலக்கும் உப்பங்கழியில் 120 சதுர கி.மீ பரப்பளவில் அமைந்துள்ள முத்துப்பேட்டை, தமிழ்நாடு வனத்துறையின் மரப்பால நடைபாதை மற்றும் படகு சவாரிக்கு புகழ்பெற்றது.",
    "latitude": 10.3333,
    "longitude": 79.5167,
    "address_en": "Muthupet Lagoon, Thiruthuraipoondi Taluk, Tiruvarur District - 614704",
    "address_ta": "முத்துப்பேட்டை, திருத்துறைப்பூண்டி வட்டம், திருவாரூர் மாவட்டம் - 614704",
    "timings_en": "07:00 AM – 05:00 PM (Daily)",
