    "name_ta": "மன்னார்குடி அருள்மிகு ராஜகோபாலசுவாமி திருக்கோவில் (தட்சிண துவாரகை)",
    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Celebrated as \"Dakshina Dwaraka\", sprawling 23-acre temple with a 156-foot Rajagopuram and Haridra Nadhi tank.",
    "short_desc_ta": "156 அடி உயர ராஜகோபுரம் மற்றும் 23 ஏக்கர் பரப்பளவிலான தென்னகத்தின் துவாரகை என்று போற்றப்படும் திருக்கோவில்.",
    "description_en": "Constructed by Chola King Kulothunga Chola I and expanded by Thanjavur Nayaks, this temple boasts 16 majestic gopurams and the colossal 23-acre Haridra Nadhi temple tank, one of the largest temple tanks in India.",
    "description_ta": "குலோத்துங்க சோழனால் தொடங்கப்பட்டு நாயக்க மன்னர்களால் விரிவுபடுத்தப்பட்ட இத்திருக்கோவிலில் உள்ள ஹரித்ரா நதி தெப்பக்குளம் 23 ஏக்கர் பரப்பளவுடன் இந்தியாவின் மிகப்பெரிய குளங்களில் ஒன்றாக விளங்குகிறது.",
