    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Premier Navagraha pilgrimage shrine of Mars (Angaraka) where Lord Shiva is worshipped as the divine healer.",
    "short_desc_ta": "நவக்கிரகங்களில் செவ்வாய் தலமாகவும், நோய் தீர்க்கும் வைத்தியநாத சுவாமி அருள் பாலிக்கும் புகழ்பெற்ற திருத்தலமாகவும் போற்றப்படுகிறது.",
    "description_en": "Revered as one of the nine Navagraha temples of the Cauvery delta, Vaitheeswaran Koil is dedicated to Lord Shiva as the supreme physician who cures all ailments. The sacred Siddhamirtham temple tank water and the holy ash prasad (Tiruchandu Urundai) are deeply venerated.",
    "description_ta": "அங்காரக பகவானின் பரிகாரத் தலமாகத் திகழும் வைத்தீஸ்வரன் கோவில், தீராத நோய்களைத் தீர்க்கும் சித்தாமிர்த தீர்த்தக்குளம் மற்றும் திருச்சாந்து உருண்டை பிரசாதத்திற்குப் பெயர் பெற்றது.",
    "latitude": 11.2017,
    "longitude": 79.7128,
