    "address_ta": "வைத்தீஸ்வரன் கோவில், சீர்காழி வட்டம், மயிலாடுதுறை மாவட்டம் - 609117",
    "timings_en": "06:00 AM – 01:00 PM, 04:00 PM – 09:00 PM",
