    "short_desc_ta": "14-ஆம் நூற்றாண்டு வரலாற்று சிறப்புமிக்க இயற்கை மலை மீது அமைந்துள்ள புகழ்பெற்ற பாலமுருகன் திருக்கோவில்.",
    "description_en": "Situated atop a small rocky hill along the Chennai-Bengaluru highway, Rathinagiri Temple dates back to the Vijayanagara period. Saint Arunagirinathar sang praises of this Lord in his Tiruppugazh. The hilltop offers serene views and an illuminated stone pathway of 150 steps.",
    "description_ta": "அருணகிரிநாதரால் பாடப்பெற்ற இரத்தினகிரி பாலமுருகன் கோவில், சென்னை-பெங்களூரு நெடுஞ்சாலையில் 150 படிகள் கொண்ட அழகிய மலை மீது அமைந்துள்ளது.",
