    "short_desc_en": "ASI protected 7th-century rock-cut monolithic shrine excavated by Pallava King Mahendravarman I.",
    "short_desc_ta": "முதலாம் மகேந்திரவர்ம பல்லவ மன்னரால் 7-ஆம் நூற்றாண்டில் ஒற்றைப் பாறையைக் குடைந்து அமைக்கப்பட்ட குடைவரைக் கோவில்.",
    "description_en": "Carved out of a free-standing boulder during the reign of King Gunabhara (Mahendravarman I), this cave temple contains an archaic Grantha-Pallava inscription proclaiming its creation as the Murari (Vishnu) shrine of Mahendra Tataka. It features massive monolithic pillars and sanctum dwarapalakas.",
    "description_ta": "பல்லவர் கால ஆரம்ப குடைவரை கட்டிடக்கலைக்கு சிறந்த சான்றான மகேந்திரவாடி கோவில், இந்திய தொல்லியல் துறையால் தேசிய நினைவுச் சின்னமாக பாதுகாக்கப்படுகிறது.",
