    "short_desc_en": "Cascading natural waterfall fed by the Attaru River tumbling down from the Yelagiri Hills slopes.",
    "short_desc_ta": "ஏலகிரி மலைச் சரிவிலிருந்து அட்டாறு நதியின் மூலமாக ஆர்ப்பரித்துக் கொட்டும் இயற்கை எழில் நீர்வீழ்ச்சி.",
    "description_en": "Located approximately 14 km from Tirupathur town, the stream falls 15 meters over granite cliffs through dense herbal forests. An adjacent hilltop temple shaped like a Shiva Lingam offers sweeping views of the valley and trekking trails across the Javadi and Yelagiri foothills.",
    "description_ta": "திருப்பத்தூரிலிருந்து 14 கி.மீ தொலைவில் உள்ள ஜலகாம்பாறை அருவி, மூலிகைக் காடுகளின் வழியே பாய்ந்து வரும் நீருடன் இயற்கை குளியலுக்கு ஏற்ற புகழ்பெற்ற இடமாகும்.",
