    "id": "tpt-vainu-bappu-observatory",
    "district_id": "tirupathur",
    "district_name_en": "Tirupathur",
    "district_name_ta": "திருப்பத்தூர்",
    "name_en": "Vainu Bappu Astronomical Observatory, Kavalur",
    "name_ta": "வைணு பாப்பு வானியல் தொலைநோக்கி நிலையம், காவலூர்",
    "category": "Heritage",
    "category_ta": "பாரம்பரியம்",
    "short_desc_en": "Premier Indian Institute of Astrophysics observatory housing the 2.34-meter Vainu Bappu optical telescope.",
    "short_desc_ta": "2.34 மீட்டர் விட்டம் கொண்ட ஆசியாவின் பிரம்மாண்ட ஆப்டிகல் தொலைநோக்கி அமைந்துள்ள இந்திய வானியல் ஆய்வு மையம்.",
    "description_en": "Operated by the Indian Institute of Astrophysics (IIA), this world-class observatory is nestled in 100 acres of forest in Kavalur in the Javadi Hills. Named after visionary astronomer M. K. Vainu Bappu, it has made landmark discoveries including rings of Uranus and atmosphere on Jupiter’s satellite Ganymede.",
    "description_ta": "ஜவ்வாது மலையின் அடர்ந்த காடுகளுக்கு நடுவே அமைந்துள்ள காவலூர் தொலைநோக்கி நிலையம், யுரேனஸ் கோளின் வளையங்கள் உள்ளிட்ட முக்கிய வானியல் கண்டுபிடிப்புகளை நிகழ்த்திய பெருமைமிக்க மையமாகும்.",
    "latitude": 12.5767,
    "longitude": 78.8267,
    "address_en": "Kavalur, Vaniyambadi Taluk, Tirupathur District - 635701",
    "address_ta": "காவலூர், வாணியம்பாடி வட்டம், திருப்பத்தூர் மாவட்டம் - 635701",
    "timings_en": "Public Visiting Hours: Every Saturday 02:00 PM – 05:00 PM (Night sky viewing from 07:00 PM weather permitting)",
    "timings_ta": "சனிக்கிழமை தோறும் மதியம் 02:00 – மாலை 05:00 (இரவு வானியல் பார்வைக்கு அனுமதி உண்டு)",
    "best_time_to_visit_en": "October to March (Clear night skies)",
    "best_time_to_visit_ta": "அக்டோபர் முதல் மார்ச் வரை",
    "entry_fee_en": "Free admission for educational visitors",
    "entry_fee_ta": "இலவச அனுமதி (கல்வி சுற்றுலா)",
