    "description_en": "Covering 100 acres at the foot of the Malaikodi hills, Sripuram Golden Temple is designed in the shape of a star (Sri Chakra) with a 1.8-km star-shaped pathway adorned with philosophical teachings leading into the golden sanctum surrounded by a green moat.",
