    "description_en": "Dating back to the Sangam era, this monumental temple on the banks of the South Pennar River is historic as the sacred meeting place of the first three Alwars (Poigai, Bhutha, and Pey Alwar). It features an imposing 192-foot Rajagopuram, the third tallest in Tamil Nadu.",
    "description_ta": "தென்பெண்ணை ஆற்றங்கரையில் அமைந்துள்ள திருக்கோவிலூர் கோவில், முதலாவாழ்வார்கள் மூவர் இணைந்து பாடிய சிறப்புடையது. இதன் 192 அடி உயர ராஜகோபுரம் தமிழகத்தின் 3-வது மிக உயர்ந்த கோபுரமாகும்.",
