    "short_desc_en": "Renowned ancient Shakti temple celebrated for the massive Amavasya (New Moon) midnight festival.",
    "short_desc_ta": "மாதந்தோறும் அமாவாசை ஊஞ்சல் உற்சவம் மற்றும் மயானக் கொள்ளை திருவிழா நடைபெறும் சக்தி வாய்ந்த திருத்தலம்.",
    "description_en": "Melmalayanur is the foremost seat of Goddess Angalamman in South India. On every Amavasya night, hundreds of thousands of devotees gather to witness the dramatic Oonjal (Swing) festival in the presence of the Goddess seated on a lotus altar.",
    "description_ta": "சிவபெருமானின் பிரம்மஹத்தி தோஷத்தை நீக்கிய தலமாகப் போற்றப்படும் மேல்மலையனூர், அமாவாசை தோறும் லட்சக்கணக்கான பக்தர்கள் கூடும் தமிழகத்தின் முக்கிய ஆன்மீகத் தலமாகும்.",
    "latitude": 12.3789,
