    "timings_en": "06:00 AM – 09:00 PM (Open round-the-clock on Amavasya nights)",
    "timings_ta": "காலை 06:00 – இரவு 09:00 (அமாவாசை இரவுகளில் விடிய விடிய திறந்திருக்கும்)",
    "best_time_to_visit_en": "Throughout the year (Amavasya days & Mahashivaratri)",
