    "description_en": "Located 12 km west of Rajapalayam town amidst dense reserve forests of the Western Ghats, Ayyanar Falls features clear mountain streams tumbling 15 meters over rocks near the historic Neeratha Ayyanar Temple, surrounded by lush mango orchards and trekking paths.",
    "description_ta": "சாஸ்தா கோவில் அருகே இயற்கை எழில் கொஞ்சும் அடர்ந்த வனப்பகுதியில் அமைந்துள்ள அய்யனார் அருவி, சுத்தமான மூலிகை நீருடன் அமைதியான சூழல் சுற்றுலாவுக்கு உகந்தது.",
