    "short_desc_ta": "12 கோடி ஆண்டுகள் பழமையான பாறை போன்ற கல் மரத் தண்டு பாதுகாக்கப்படும் இந்திய புவியியல் ஆய்வுத் தளம்.",
    "description_en": "Discovered in 1940 by renowned geologist Dr. M. S. Krishnan, this petrified conifer tree trunk measures over 18 meters in length and belongs to the Cretaceous geological period when South India was part of Gondwanaland. It is one of India’s most important geological monuments.",
    "description_ta": "1940-ல் டாக்டர் எம்.எஸ். கிருஷ்ணனால் கண்டுபிடிக்கப்பட்ட இந்த கல் மரம், 120 மில்லியன் ஆண்டுகளுக்கு முந்தைய கிரெட்டேசியஸ் காலத்தைச் சேர்ந்த அறிவியல் மற்றும் புவியியல் அதிசயப் பொக்கிஷமாகும்.",
