    "category": "Temple",
    "category_ta": "கோவில்",
    "short_desc_en": "Celebrated ancient temple open exclusively on Mondays and Fridays, associated with the epic Silappathikaram.",
    "short_desc_ta": "திங்கள் மற்றும் வெள்ளிக்கிழமைகளில் மட்டுமே திறக்கப்படும் வரலாற்று சிறப்புமிக்க சிலப்பதிகார தொடர்பு கொண்ட அம்மன் கோவில்.",
    "description_en": "Legend says Kannagi rested here on her way from Madurai to Kodungallur. The temple is unique because the sanctum is open to public darshan only twice a week (Mondays and Fridays) as the Goddess is said to abide with the deity Chelliamman on the remaining days.",
    "description_ta": "கண்ணகிக்கு அடைக்கலம் கொடுத்த புண்ணிய தலமான சிறுவாச்சூர், வாரத்தில் திங்கள் மற்றும் வெள்ளிக்கிழமைகளில் மட்டும் திறக்கப்பட்டு லட்சக்கணக்கான பக்தர்களை ஈர்க்கிறது.",
