    "description_en": "Standing on a small rocky hill near Velayuthampalayam, Pugamalai features natural rock caverns with polished stone beds where Jain monks resided over 2,200 years ago. An ancient Tamil-Brahmi inscription mentions three generations of Chera rulers who patronized the site.",
