    "description_en": "Situated at an elevation of 1,000 meters in the Eastern Ghats, Javadi Hills is famous for its cool climate, fruit orchards, and tribal heritage. Beeman Falls plunges over lush granite steps into deep natural forest pools popular for swimming and eco-trekking.",
    "description_ta": "கிழக்குத் தொடர்ச்சி மலையில் 1,000 மீட்டர் உயரத்தில் அமைந்துள்ள ஜவ்வாது மலை, சந்தன சோலைகளும் பீமன் அருவியும் கொண்ட சிறந்த சூழல் சுற்றுலா தலமாகும்.",
