    "short_desc_en": "Medieval 13th-century capital of the Sambuvarayar kings with historic rock excavations and Shakti temple.",
    "short_desc_ta": "13-ஆம் நூற்றாண்டு சம்புவராய மன்னர்களின் தலைநகரமான வரலாற்று கோட்டை இடிபாடுகள் மற்றும் புகழ்பெற்ற ரேணுகாம்பாள் கோவில்.",
    "description_en": "Padaveedu was the formidable capital of the 13th-century Sambuvarayar dynasty. Excavations by the State Archaeology Department unearthed ancient royal palaces, stone water channels, and fortifications. The village is home to the renowned Sri Renukambal Temple and Ramachandra Perumal Temple.",
    "description_ta": "சம்புவராயர்களின் தலைநகரமான படவேட்டில் தொல்லியல் துறை அகழாய்வு செய்த அரண்மனை அடித்தளங்கள் மற்றும் சக்தி வாய்ந்த ரேணுகாம்பாள் திருக்கோவில் அமைந்துள்ளது.",
