    "short_desc_en": "State Department of Geology museum preserving Cretaceous marine ammonite fossils from a submerged prehistoric sea.",
    "short_desc_ta": "10 கோடி ஆண்டுகளுக்கு முன் கடலாக இருந்த அரியலூரில் கண்டெடுக்கப்பட்ட கடல்வாழ் உயிரின படிமங்களின் அருங்காட்சியகம்.",
    "description_en": "Ariyalur is internationally famous among paleontologists as a fossil treasure house. This museum exhibits prehistoric ammonites, belemnites, nautiloids, and dinosaur bone fragments excavated from the sedimentary limestone beds of Ariyalur, proving the region was once under a Cretaceous ocean.",
    "description_ta": "அரியலூர் நிலப்பரப்பு பல கோடி ஆண்டுகளுக்கு முன் பெருங்கடலாக இருந்ததை நிரூபிக்கும் அரிய அம்மோனைட் மற்றும் டைனோசர் எலும்பு படிமங்கள் இங்கு காட்சிப்படுத்தப்பட்டுள்ளன.",
